from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.models import Payment
from ledgerly.adjustments import refund
from ledgerly.errors import BillingError

T0 = datetime(2026,1,1,tzinfo=timezone.utc)
def mk(status="captured"):
    return Payment("p","i",Decimal("100.00"),status=status,created_at=T0,captured_at=T0)

p=mk(); refund(p,Decimal("40.00"),T0); refund(p,Decimal("60.00"),T0)
assert p.refunded_amount==Decimal("100.00") and p.status=="refunded", p
print("full refund ok:", p)

p=mk()
try: refund(p,Decimal("100.01"),T0); print("FAIL over-refund")
except BillingError as e: print("over-refund rejected:", e.code)

p=mk("authorized")
try: refund(p,Decimal("1.00"),T0); print("FAIL non-captured")
except BillingError as e: print("non-captured rejected:", e.code)

p=mk()
try: refund(p,1.0,T0); print("FAIL float")
except BillingError as e: print("float rejected:", e.code)

p=mk()
try: refund(p,Decimal("0"),T0); print("FAIL zero")
except BillingError as e: print("zero rejected:", e.code)
EOF"}

